CREATE TABLE `account_user` ( `id` varchar(36) NOT NULL PRIMARY KEY, `display_name` varchar(128) NOT NULL, `password_hash` text, `created_at` bigint NOT NULL, `created_by` varchar(36) NOT NULL, `updated_at` bigint NOT NULL, `updated_by` varchar(36) NOT NULL, `row_version` bigint NOT NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE `account_auth_setting` ( `id` varchar(36) NOT NULL PRIMARY KEY, `mode` varchar(16) NOT NULL, `created_at` bigint NOT NULL, `created_by` varchar(36) NOT NULL, `updated_at` bigint NOT NULL, `updated_by` varchar(36) NOT NULL, `row_version` bigint NOT NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE `account_recovery_code` ( `id` varchar(36) NOT NULL PRIMARY KEY, `user_id` varchar(36) NOT NULL, `code_hash` text NOT NULL, `used_at` bigint, `created_at` bigint NOT NULL, `created_by` varchar(36) NOT NULL, `updated_at` bigint NOT NULL, `updated_by` varchar(36) NOT NULL, `deleted_at` bigint, `delete_token` varchar(36) NOT NULL ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE INDEX `ix_account_recovery_code_user_id` ON `account_recovery_code` (`user_id`);
CREATE TABLE `account_login_attempt` ( `user_id` varchar(36) NOT NULL, `failed_count` int NOT NULL, `last_failed_at` bigint NOT NULL, `locked_until` bigint, UNIQUE KEY `uq_account_login_attempt_user_id` (`user_id`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
